var t=`0826-butter-chicken`;var n=`world-0826`;var a=`IN`;var s=`south-asia`;var r=4;var o=110;var g={en:`Butter Chicken`,ua:`Батер чікен`};var l={en:`Butter Chicken is a India dish made with chicken thigh, plain yogurt, lemon juice, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Батер чікен, страва кухні країни Індія. Основні складники: куряче стегно, натуральний йогурт, лимонний сік, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 60 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 60 хвилин.`,t:[`marinating`],m:60,i:[[`chicken-thigh`,760,`g`],[`plain-yogurt`,180,`g`],[`garam-masala`,9,`g`],[`kashmiri-chili-powder`,5,`g`],[`lemon-juice`,30,`ml`]]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`canola-oil`,20,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`unsalted-butter`,70,`g`],[`yellow-onion`,190,`g`],[`ginger-garlic-paste`,35,`g`],[`tomato-passata`,450,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`heavy-cream`,190,`ml`],[`kasuri-methi`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var h={slug:t,id:n,country:`IN`,region:s,servings:4,minutes:110,title:g,text:l,steps:u};export{a as country,h as default,n as id,o as minutes,s as region,r as servings,t as slug,u as steps,l as text,g as title};